WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_m_equation'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '工程与方程', 'kp-eng-m-equation', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "工程与方程综合"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "无法用特值法秒杀的工程题。必须设未知数，利用时间等式或工作量等式破局。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当题目中出现了两个以上的绝对数量，或者时间差极为复杂时。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心方程模型"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "最常用的等式是【总工作量相等】或【时间差相等】。"}]}, {"type": "katexBlock", "attrs": {"content": "P_{甲} \\times T_{甲} = P_{乙} \\times T_{乙} = W_{总}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[判断无法赋公倍数(比如时间全是未知数)] --> B[勇敢地设未知数 X (通常设效率或基本时间)]\nB --> C[利用题干条件写出两套完成工程的方案表达式]\nC --> D[用等号连接两套方案(因为总工程量是同一个)]\nD --> E[解方程得出基础变量, 进而求得目标值]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲乙两人做一项工程。如果甲先做 2 天，乙再做 3 天可完成；如果甲先做 3 天，乙再做 1 天也可完成。已知甲每天比乙多做 5 个零件。求总数？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识破特征：有绝对数量（5个），不能用纯特值法。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "设未知数：设乙的效率为 x，则甲的效率为 x + 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列总量方程：方案1总量 = 2(x+5) + 3x。方案2总量 = 3(x+5) + 1x。两者相等！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "解方程：2x + 10 + 3x = 3x + 15 + x。5x + 10 = 4x + 15。解得 x = 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求总量：乙的效率是 5，甲是 10。代入方案1：2×10 + 3×5 = 35 个。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "害怕列方程：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不要觉得公考数学列方程就很 low。当特值法走不通时，硬凑特值反而会浪费大量时间。果断设 x 是最高效的保底手段。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "训练快速提取“两套方案”的能力。这就是等号的两边。"}]}]}$$ AS jsonb), NULL, '工程与方程的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "工程与方程"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_m_equation", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
